example.good:
type Reader interface {
  Read(p []byte) (n int, err error)
}

example.bad:
type BigInterface interface {
  Read() []byte
  Write([]byte) error
  Close() error
  // ... many more methods
}

convention.template:
// Standard file organization:
// - types.go - Type definitions and interfaces
// - methods.go - Methods for types
// - helpers.go - Helper functions
// - errors.go - Custom error types
// - doc.go - Package documentation
// - {type}_test.go - Tests for specific type
// - integration_test.go - Integration tests

// Always check errors
result, err := someFunction()
if err != nil {
    return fmt.Errorf("context: %w", err)
}

// Wrap errors with context
if err != nil {
    return fmt.Errorf("operation failed: %w", err)
}

// Use sentinel errors for expected cases
var ErrNotFound = errors.New("not found")

example.code:
func worker(ctx context.Context, wg *sync.WaitGroup, jobs <-chan Job) {
    defer wg.Done()

    for {
        select {
        case <-ctx.Done():
            return
        case job, ok := <-jobs:
            if !ok {
                return
            }
            process(job)
        }
    }
}

// Producer
func produce(ctx context.Context, out chan<- Result) {
    defer close(out)
    for _, item := range items {
        select {
        case <-ctx.Done():
            return
        case out <- process(item):
        }
    }
}

// Consumer
func consume(in <-chan Result) {
    for result := range in {
        handle(result)
    }
}
